const maxLen = 280;
const text = items[0].json.output;
const parts = [];
let remaining = text.trim();

while (remaining.length > 0) {
  if (remaining.length <= maxLen) {
    parts.push(remaining.trim());
    break;
  }

  const chunk = remaining.slice(0, maxLen);
  let splitPos = -1;

  const dnPos = chunk.lastIndexOf('\n\n');
  if (dnPos > maxLen * 0.4) {
    splitPos = dnPos + 2;
  }

  if (splitPos === -1) {
    const snPos = chunk.lastIndexOf('\n');
    if (snPos > maxLen * 0.5) {
      splitPos = snPos + 1;
    }
  }

  if (splitPos === -1) {
    const puncts = ['. ', '! ', '? ', ': '];
    let lastP = -1;
    for (const p of puncts) {
      const pos = chunk.lastIndexOf(p);
      if (pos > lastP && pos > maxLen * 0.4) lastP = pos;
    }
    if (lastP !== -1) splitPos = lastP + 2;
  }

  if (splitPos === -1) splitPos = maxLen;

  parts.push(remaining.slice(0, splitPos).trim());
  remaining = remaining.slice(splitPos).trim();
}

return parts
  .filter(p => p.length > 0)
  .map(p => ({ json: { chunk: p } }));

const staticData = $getWorkflowStaticData('global');
const numero = $input.item.json.data?.key?.remoteJid || $input.item.json.remoteJid || '';
const agora = Date.now();
const janela = 10 * 60 * 1000;
const limite = 20;

if (!staticData.rateLimit) staticData.rateLimit = {};

for (const num of Object.keys(staticData.rateLimit)) {
  staticData.rateLimit[num] = staticData.rateLimit[num].filter(t => agora - t < janela);
  if (staticData.rateLimit[num].length === 0) delete staticData.rateLimit[num];
}

const historico = staticData.rateLimit[numero] || [];

if (historico.length >= limite) {
  console.log('[RATE LIMIT] Bloqueado: ' + numero + ' (' + historico.length + ' msgs em 10min)');
  return [];
}

historico.push(agora);
staticData.rateLimit[numero] = historico;

return [{ json: { ...$input.item.json, _rateCount: historico.length } }];
